#!/usr/bin/env python3
"""Generate .resw and .wxl localization files for AgentRedactor.

Reads the master English Resources.resw and existing German Resources.resw,
then emits localized Resources.resw files for 29 new languages plus a
regenerated German file, together with matching .wxl installer files.

Run from the repository root with a standard Python 3 interpreter:
    python AgentRedactor/generate_localizations.py
"""

from __future__ import annotations

