# -----------------------------------------------------------------------------
# Parsing helpers
# -----------------------------------------------------------------------------
def parse_resw(path: Path) -> Dict[str, str]:
    """Return a dict of {name: value} from a .resw file."""
    tree = ET.parse(path)
    root = tree.getroot()
    data: Dict[str, str] = {}
    for elem in root.findall("data"):
        name = elem.get("name")
        value_elem = elem.find("value")
        if name is not None and value_elem is not None and value_elem.text is not None:
            data[name] = value_elem.text
    return data


def parse_resw_preserve(path: Path) -> ET.ElementTree:
    """Parse a .resw file preserving comments and formatting as much as possible."""
    return ET.parse(path)


def parse_wxl(path: Path) -> ET.ElementTree:
    """Parse a .wxl installer localization file."""
    return ET.parse(path)


def escape_xml_text(text: str) -> str:
    """Escape text for an XML text node, preserving the resw conventions."""
    # xml.sax.saxutils.escape handles &, <, >; we also need apostrophe and quote
    # for general XML safety, but resw values typically only need the first three.
    return (
        text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace("\"", "&quot;")
        .replace("'", "&apos;")
    )


def indent_xml(elem: ET.Element, level: int = 0, indent_str: str = "  ") -> None:
    """Add pretty-print indentation to an ElementTree element."""
    i = "\n" + level * indent_str
    if len(elem):
        if not elem.text or not elem.text.strip():
            elem.text = i + indent_str
        if not elem.tail or not elem.tail.strip():
            elem.tail = i
        for child in elem:
            indent_xml(child, level + 1, indent_str)
        if not child.tail or not child.tail.strip():  # type: ignore[has-type]
            child.tail = i  # type: ignore[has-type]
    else:
        if level and (not elem.tail or not elem.tail.strip()):
            elem.tail = i


