# -----------------------------------------------------------------------------
# Build the unified TRANSLATIONS dictionary
# -----------------------------------------------------------------------------
# For every language, fill in missing entries from COPY_AS_IS or English fallback.
def build_translations(en_data: Dict[str, str]) -> Dict[str, Dict[str, str]]:
    """Return {language_tag: {english_value: translated_value}}."""
    translations: Dict[str, Dict[str, str]] = {}
    for lang in LANGUAGES:
        tag = lang["tag"]
        lang_dict = LANG_TRANSLATIONS.get(tag, {})
        full: Dict[str, str] = {}
        for name, english in en_data.items():
            if english in COPY_AS_IS:
                full[english] = english
            elif english in lang_dict:
                full[english] = lang_dict[english]
            else:
                # Fallback to English with a warning so the script never breaks.
                print(f"WARNING: Missing translation for '{english}' in {tag}")
                full[english] = english
        translations[tag] = full
    return translations

