# -----------------------------------------------------------------------------
# .resw generation
# -----------------------------------------------------------------------------
def generate_resw(
    en_tree: ET.ElementTree,
    en_data: Dict[str, str],
    translations: Dict[str, str],
    extra_data: Dict[str, str],
    output_path: Path,
) -> None:
    """Write a localized .resw file preserving structure from the English tree."""
    root = copy.deepcopy(en_tree.getroot())

    # Update existing data entries with translations.
    for elem in root.findall("data"):
        name = elem.get("name")
        value_elem = elem.find("value")
        if name is None or value_elem is None or value_elem.text is None:
            continue
        english = en_data.get(name)
        if english is not None and english in translations:
            value_elem.text = translations[english]

    # Append the new language display keys (used by the language picker).
    for key, value in sorted(extra_data.items()):
        data_elem = ET.SubElement(root, "data", {"name": key, "{http://www.w3.org/XML/1998/namespace}space": "preserve"})
        value_elem = ET.SubElement(data_elem, "value")
        value_elem.text = value

    indent_xml(root)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    tree = ET.ElementTree(root)
    tree.write(output_path, encoding="utf-8", xml_declaration=True)


# -----------------------------------------------------------------------------
# .wxl generation
# -----------------------------------------------------------------------------
WIX_NS = "http://schemas.microsoft.com/wix/2006/localization"
ET.register_namespace("", WIX_NS)


def generate_wxl(
    en_wxl_tree: ET.ElementTree,
    tag: str,
    lcid: int,
    app_description: str,
    downgrade_message: str,
    output_path: Path,
) -> None:
    """Write a localized .wxl installer file."""
    root = copy.deepcopy(en_wxl_tree.getroot())
    root.set("Culture", tag)

    for string_elem in root.findall(f"{{{WIX_NS}}}String"):
        sid = string_elem.get("Id")
        if sid == "LCID":
            string_elem.text = str(lcid)
        elif sid in ("ProductDescription", "ShortcutDescription"):
            string_elem.text = app_description
        elif sid == "DowngradeErrorMessage":
            string_elem.text = downgrade_message

    indent_xml(root)
    tree = ET.ElementTree(root)
    tree.write(output_path, encoding="utf-8", xml_declaration=True)


